1	/**
2	 * Organization Module — single source of truth for departments, phases, and
3	 * the agent registry. Replaces the hardcoded AGENT_PIPELINE / AGENT_ROLES
4	 * constants previously in server.js.
5	 *
6	 * Data lives in ~/.claude/org/:
7	 *   - departments.json — department + phase definitions
8	 *   - registry.json    — per-agent record (department, phase, reportsTo,
9	 *                        experience, level, skills, status, hire date)
10	 *
11	 * This module is pure — it reads/writes JSON. Experience computation lives
12	 * in src/experience.js and reads from here.
13	 */
